def transform(g):
    h,w=len(g),len(g[0])
    # multi-cell runs to find dominant direction and offsets
    main_offs={}; anti_offs={}
    seen=set()
    for r in range(h):
        for c in range(w):
            if g[r][c] and (r,c) not in seen:
                col=g[r][c]
                # main run
                rr,cc=r,c
                while rr>0 and cc>0 and g[rr-1][cc-1]==col: rr,cc=rr-1,cc-1
                r2,c2=rr,cc; cells=[]
                while r2<h and c2<w and g[r2][c2]==col:
                    cells.append((r2,c2)); r2+=1; c2+=1
                if len(cells)>1:
                    seen.update(cells)
                    main_offs[cells[0][1]-cells[0][0]]=(col,len(cells))
                else:
                    main_offs.setdefault(c-r,(col,1))
                # anti run
                rr,cc=r,c
                while rr>0 and cc<w-1 and g[rr-1][cc+1]==col: rr,cc=rr-1,cc+1
                r2,c2=rr,cc; cells=[]
                while r2<h and c2>=0 and g[r2][c2]==col:
                    cells.append((r2,c2)); r2+=1; c2-=1
                if len(cells)>1:
                    anti_offs[cells[0][0]+cells[0][1]]=(col,len(cells))
                else:
                    anti_offs.setdefault(r+c,(col,1))
    has_main_multi=any(L>1 for _,L in main_offs.values())
    has_anti_multi=any(L>1 for _,L in anti_offs.values())
    if not has_main_multi and not has_anti_multi:
        return [row[:] for row in g]
    if has_main_multi and (not has_anti_multi or len(main_offs)>=len(anti_offs)):
        offs, keymain = main_offs, True
    else:
        offs, keymain = anti_offs, False
    P=len(offs)
    slot={}
    lost=[]
    for o,(col,L) in sorted(offs.items()):
        s=o%P
        if s in slot:
            if L>slot[s][1]: lost.append(slot[s][0]); slot[s]=(col,L)
            else: lost.append(col)
        else:
            slot[s]=(col,L)
    fill=lost[0] if lost else list(offs.values())[0][0]
    out=[[0]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            k=(c-r)%P if keymain else (r+c)%P
            out[r][c]=slot[k][0] if k in slot else fill
    for r in range(h):
        for c in range(w):
            if g[r][c]: out[r][c]=g[r][c]
    return out

